function T(s,v){const d=DICT[LANG],o=(d&&d[s])||s;return v?o.replace(/\{(\w+)\}/g,(m,k)=>k in v?v[k]:m):o}
// Like T, but escapes the values you pass in, for text that goes into HTML.
function TH(s,v){const d=DICT[LANG],o=(d&&d[s])||s;return v?o.replace(/\{(\w+)\}/g,(m,k)=>k in v?esc(v[k]):m):o}
function applyStatic(){
 document.documentElement.lang=HTML_LANG[LANG];
 document.title=T('Haggle Market Arena: Where Price Meets Strategy');
 document.querySelectorAll('[data-i]').forEach(e=>{e.textContent=T(e.getAttribute('data-i'))});
 document.querySelectorAll('[data-ial]').forEach(e=>e.setAttribute('aria-label',T(e.getAttribute('data-ial'))));
 const l=document.getElementById('lang');if(l)l.value=LANG;
}
function setLang(l){if(!LANGS[l])l='en';LANG=l;LOCALE=LOCALES[l];NF=null;try{localStorage.setItem('haggle.lang',l)}catch(e){}}
function initLang(){
 let l=null;try{l=localStorage.getItem('haggle.lang')}catch(e){}
 if(!LANGS[l||'']){const n=((navigator.languages&&navigator.languages[0])||navigator.language||'en').toLowerCase();l=n.indexOf('pcm')===0?'pcm':n.indexOf('fr')===0?'fr':'en'}
 LANG=l;LOCALE=LOCALES[l];
}
